// Lọc công nợ quá hạn + dựng thông báo. TẤT ĐỊNH — không gọi LLM:
// danh sách nợ là con số, template cố định đủ rõ, không có gì để 'diễn giải'.
// (retail_debt_reminder gọi Brain viết lời vì nhắn TRỰC TIẾP cho khách nợ;
//  bản này chỉ báo NỘI BỘ cho chủ DN nên không cần.)
const today = new Date().toISOString().slice(0, 10);
const rows = $input.all().map(i => i.json);
const vn = n => new Intl.NumberFormat('vi-VN').format(Number(n));

const overdue = rows.filter(r =>
  (r.status === 'open' || r.status === 'partial') &&
  r.due_date && String(r.due_date) < today
).map(r => ({
  ...r,
  remaining: Number(r.amount) - Number(r.paid_amount || 0),
  days_late: Math.floor((new Date(today) - new Date(r.due_date)) / 86400000)
})).filter(r => r.remaining > 0)
  .sort((a, b) => b.days_late - a.days_late);

if (!overdue.length) {
  return [{ json: { has_overdue: false } }];
}

const total = overdue.reduce((s, r) => s + r.remaining, 0);
const lines = overdue.map(r =>
  '• **' + r.customer_name + '** — còn nợ **' + vn(r.remaining) + ' đ**' +
  ', quá hạn ' + r.days_late + ' ngày (hạn ' + r.due_date + ', mã ' + r.quote_id + ')'
).join('\n');

const body = { embeds: [{
  title: '💰 Công nợ quá hạn — ' + overdue.length + ' khách, tổng ' + vn(total) + ' đ',
  color: 15158332,
  description: lines.slice(0, 3800),
  footer: { text: 'ANSER Logistics • nhắc mỗi thứ 2' },
  timestamp: new Date().toISOString()
}]};

return [{ json: { has_overdue: true, discord_body: JSON.stringify(body) } }];
